# Generated by FWShift: Windows Defender Firewall rules for one host, created with New-NetFirewallRule. Read the
# report first: what is not written is listed there.
#
#   powershell -ExecutionPolicy Bypass -File THIS_FILE -DryRun   shows what it would create (-WhatIf), creates nothing
#   powershell -ExecutionPolicy Bypass -File THIS_FILE           creates the rules (as administrator)
#
# -PolicyStore names another store than the local one (PersistentStore), such as a GPO: -PolicyStore 'example.com\GPO'.
# Every rule is created in the rule group FWShift; nothing is deleted and no profile setting is changed. A rule of
# that group, or of one of its names, stops the script before anything is created; a call Windows refuses stops it
# where it is. To take the rules away again: Remove-NetFirewallRule -Group 'FWShift'
#
# Windows evaluates these rules together with every other rule of the host: a block rule beats an allow rule, and
# what no rule matches gets the profile's default. Block rules are written without what the allow rules above them
# allowed in the source; see the report.
[CmdletBinding()]
param([switch]$DryRun, [string]$PolicyStore = 'PersistentStore')
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$Group = 'FWShift'
$NamePrefix = 'FWShift-'
# The profiles in which the policy denies outbound connections no rule allows: their default must be Block.
$OutboundBlock = @('Domain', 'Private', 'Public')
$Created = 0
function Add-Rule([hashtable]$Rule) {
    if ($DryRun) { New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore -WhatIf; return }
    $null = New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore
    $script:Created++
}
if (-not $DryRun) {
    $taken = @(Get-NetFirewallRule -PolicyStore $PolicyStore -ErrorAction SilentlyContinue |
        Where-Object { $_.Group -eq $Group -or $_.Name -like ($NamePrefix + '*') })
    if ($taken.Count -gt 0) {
        throw ('rules of the group ' + $Group + ' or named ' + $NamePrefix + '... exist in ' + $PolicyStore + ' already (' +
            $taken[0].Name + '); nothing was created')
    }
}
foreach ($fwProfile in @(Get-NetFirewallProfile -PolicyStore ActiveStore)) {
    $name = [string]$fwProfile.Name
    if ([string]$fwProfile.Enabled -eq 'False') { Write-Warning ('the firewall is off in the profile ' + $name + ': no rule applies there') }
    if ([string]$fwProfile.DefaultInboundAction -eq 'Allow') {
        Write-Warning ('the profile ' + $name + ' allows inbound connections no rule blocks; this policy needs Block ' +
            '(Set-NetFirewallProfile -Name ' + $name + ' -DefaultInboundAction Block)')
    }
    if ($OutboundBlock -contains $name -and [string]$fwProfile.DefaultOutboundAction -ne 'Block') {
        Write-Warning ('the profile ' + $name + ' allows outbound connections that this policy denies; to deny them ' +
            'set Set-NetFirewallProfile -Name ' + $name + ' -DefaultOutboundAction Block')
    }
}

Add-Rule @{ Name = 'FWShift-Block_Bad-1'; DisplayName = 'Block Bad (1)'; Description = 'FWShift: Block Bad'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; LocalAddress = @('192.0.2.66', '203.0.113.0/25') }
Add-Rule @{ Name = 'FWShift-Block_Bad-2'; DisplayName = 'Block Bad (2)'; Description = 'FWShift: Block Bad'; Direction = 'Outbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; RemoteAddress = @('192.0.2.66', '203.0.113.0/25') }
Add-Rule @{ Name = 'FWShift-Admin_SSH-1'; DisplayName = 'Admin SSH (1)'; Description = 'FWShift: Admin SSH'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('22'); RemoteAddress = @('10.10.5.10-10.10.5.20') }
Add-Rule @{ Name = 'FWShift-Admin_SSH-2'; DisplayName = 'Admin SSH (2)'; Description = 'FWShift: Admin SSH'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('22'); LocalAddress = @('10.10.5.10-10.10.5.20') }
Add-Rule @{ Name = 'FWShift-Web_Out-1'; DisplayName = 'Web Out (1)'; Description = 'FWShift: Web Out'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('80', '443', '8000-8010') }
Add-Rule @{ Name = 'FWShift-Web_Out-2'; DisplayName = 'Web Out (2)'; Description = 'FWShift: Web Out'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('80', '443', '8000-8010') }
Add-Rule @{ Name = 'FWShift-Web_In-1'; DisplayName = 'Web In (1)'; Description = 'FWShift: Web In'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('443'); LocalAddress = @('10.20.0.10') }
Add-Rule @{ Name = 'FWShift-Web_In-2'; DisplayName = 'Web In (2)'; Description = 'FWShift: Web In'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('443'); RemoteAddress = @('10.20.0.10') }
Add-Rule @{ Name = 'FWShift-Mail_In-1'; DisplayName = 'Mail In (1)'; Description = 'FWShift: Mail In'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('2525'); LocalAddress = @('10.20.0.25') }
Add-Rule @{ Name = 'FWShift-Mail_In-2'; DisplayName = 'Mail In (2)'; Description = 'FWShift: Mail In'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('2525'); RemoteAddress = @('10.20.0.25') }
Add-Rule @{ Name = 'FWShift-Staff_Only-1'; DisplayName = 'Staff Only (1)'; Description = 'FWShift: Staff Only'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('3389'); LocalAddress = @('10.20.0.10') }
Add-Rule @{ Name = 'FWShift-Staff_Only-2'; DisplayName = 'Staff Only (2)'; Description = 'FWShift: Staff Only'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('3389'); RemoteAddress = @('10.20.0.10') }
Add-Rule @{ Name = 'FWShift-Ping-1'; DisplayName = 'Ping (1)'; Description = 'FWShift: Ping'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4'; IcmpType = @('8') }
Add-Rule @{ Name = 'FWShift-Ping-2'; DisplayName = 'Ping (2)'; Description = 'FWShift: Ping'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4'; IcmpType = @('8') }
Add-Rule @{ Name = 'FWShift-Lab_Tunnel-1'; DisplayName = 'Lab Tunnel (1)'; Description = 'FWShift: Lab Tunnel'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = '47' }
Add-Rule @{ Name = 'FWShift-Lab_Tunnel-2'; DisplayName = 'Lab Tunnel (2)'; Description = 'FWShift: Lab Tunnel'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = '47' }

# Not written:
#   rule DMZ Updates: not written, see the report
#   rule Guests Out: disabled in the source, not written

if (-not $DryRun) { Write-Host ('Done: ' + $Created + ' rules created in the group ' + $Group) }
